// 1. Pichle node (Filter Latest Prices) se saara Mandi ka data ek list mein nikalna
const mandiItems = $('filter_latest_dates').all(); 

// 2. HTTP Request node se aaya hua naya Geocoding (Lat/Lon) ka saara data
const geoItems = $input.all(); 

let finalOutput = [];

// 3. Dono lists ko ek saath loop karte hain taaki data match ho jaye
for (let i = 0; i < geoItems.length; i++) {

    // Check karte hain ki us index par pichla Mandi data majood hai ya nahi
    let mandiData = mandiItems[i] ? mandiItems[i].json : {};
    let geoResult = geoItems[i].json;

    let lat = 0;
    let lon = 0;

    // 4. Lat/Lon nikalne ka sahi logic (Array bug fixed)
    if (Array.isArray(geoResult) && geoResult.length > 0) {
        // Agar data array ke andar hai, toh pehle element [0] se uthana padega
        lat = parseFloat(geoResult[0].lat || 0); 
        lon = parseFloat(geoResult[0].long || 0);
    } else if (geoResult.lat && geoResult.lon) {
        // Agar seedha object hai
        lat = parseFloat(geoResult.lat || 0);
        lon = parseFloat(geoResult.lon || 0);
    }

    // 5. Purane Mandi data aur naye Lat/Lon ko jod kar naya result banana
    finalOutput.push({
        json: {
            State: mandiData.State,
            District: mandiData.District,
            Market: mandiData.Market,
            Commodity: mandiData.Commodity,
            Arrival_Date: mandiData.Arrival_Date,
            Modal_Price: mandiData.Modal_Price,
            Min_Price: mandiData.Min_Price,
            Max_Price: mandiData.Max_Price,
            Mandi_Lat: lat,
            Mandi_Lon: lon
        }
    });
}

// 6. Final merged data ko output kar dena
return finalOutput;

// 1. Sabhi 5 districts ke hazaron records ko ek badi list mein ikattha karna
let allRecords = [];

for (const item of $input.all()) {
    // Check karte hain ki kya API ne sach mein 'records' bheje hain
    if (item.json.records && item.json.records.length > 0) {
        // Un sabko hamari ek master list mein jod do
        allRecords = allRecords.concat(item.json.records);
    }
}

// 2. Humein sirf Unique Mandis ka LATEST bhav chahiye
let uniqueMandis = {};
let finalCleanMandis = [];

// API ka data pehle se hi 'desc' (ultex kram) mein sort hokar aaya hai.
// Iska matlab list mein jo mandi pehli baar dikhegi, wahi uska sabse latest bhav hoga!
for (const record of allRecords) {
    let marketName = record.Market;

    // Agar ye mandi pehli baar dikhi hai aur iska Modal_Price 0 nahi hai
    if (!uniqueMandis[marketName] && record.Modal_Price && record.Modal_Price > 0) {

        // Is mandi ko 'dekh liya gaya hai' aisi list mein daal do taaki iska purana data ignore ho jaye
        uniqueMandis[marketName] = true;

        // Is fresh data ko n8n ke 'json' dabbe mein pack karke aage bhej do
        finalCleanMandis.push({
            json: {
                State: record.State,
                District: record.District,
                Market: marketName,
                Commodity: record.Commodity,
                Arrival_Date: record.Arrival_Date,
                Modal_Price: parseFloat(record.Modal_Price), // Ise number bana diya taaki aage math ho sake
                Min_Price: record.Min_Price,
                Max_Price: record.Max_Price
            }
        });
    }
}

// 3. Ye clean 15-20 mandiyon ki list agle node ko pass kar do
return finalCleanMandis;

// 1. INPUTS node se kisan ki location aur quantity uthao
const inputData = $('Edit Fields1').first().json;

// Number() का इस्तेमाल करो। यह स्ट्रिंग को नंबर में बदल देगा और अगर पहले से नंबर है तो एरर नहीं देगा।
const userLat = Number(inputData.lat);
const userLon = Number(inputData.long);
const cropQuantity = inputData.cropQuantity ? Number(inputData.cropQuantity) : 100; 

// 2. Distance nikalne ka formula (Haversine Formula - in KM)
function getDistance(lat1, lon1, lat2, lon2) {
  const R = 6371; // Earth radius
  const dLat = (lat2 - lat1) * (Math.PI / 180);
  const dLon = (lon2 - lon1) * (Math.PI / 180);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) *
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

let scoredMandis = [];

// 3. Har mandi ka Kiraya aur Munafa nikalna
for (const item of $input.all()) {
    const mandi = item.json;

    // Agar location theek se aayi hai tabhi math karo
    if(mandi.Mandi_Lat && mandi.Mandi_Lon && mandi.Mandi_Lat !== 0) {

        // Doori nikalo
        const distanceKM = getDistance(userLat, userLon, mandi.Mandi_Lat, mandi.Mandi_Lon);

        // Transport Cost (Maan lo 1 quintal ko 1 KM le jane ka ₹3 lagta hai)
        const transportCostPerQuintal = distanceKM * 3; 

        // Asli Bhav (Bhav minus Kiraya)
        const effectivePrice = mandi.Modal_Price - transportCostPerQuintal;

        // Total Asli Munafa
        const totalProfit = effectivePrice * cropQuantity;

        scoredMandis.push({
            json: {
                ...mandi, 
                Distance_KM: parseFloat(distanceKM.toFixed(2)),
                Transport_Cost_Per_Q: parseFloat(transportCostPerQuintal.toFixed(2)),
                Effective_Price: parseFloat(effectivePrice.toFixed(2)),
                Total_Estimated_Profit: parseFloat(totalProfit.toFixed(2))
            }
        });
    }
}

// 4. Sabhi calculated items aage bhej do
return scoredMandis;

// N8n se input items get karna
const items = $input.all();

// N8n ke {json: ...} structure se apna original data array nikalna
const data = items.map(item => item.json);

// Date ko 'DD/MM/YYYY' format se JavaScript Date object me badalne ka function
function parseDate(dateStr) {
    if (!dateStr) return new Date(0);
    const parts = dateStr.split('/');
    if (parts.length === 3) {
        // Javascript me month 0 se start hota hai, isliye parts[1] - 1 kiya hai
        return new Date(parts[2], parts[1] - 1, parts[0]);
    }
    return new Date(0);
}

// Step 1: Data me majood sabse latest date dhundhna
let latestDate = new Date(0);
data.forEach(row => {
    if (row.Arrival_Date) {
        let currentDate = parseDate(row.Arrival_Date);
        if (currentDate > latestDate) {
            latestDate = currentDate;
        }
    }
});

// Step 2: Latest date se 30 din pehle ki (cutoff) date calculate karna
let cutoffDate = new Date(latestDate);
cutoffDate.setDate(cutoffDate.getDate() - 30);

// Step 3: Sirf unhi records ko filter karna jo latest date aur 30 din pehle ki date ke beech ke hain
const filteredData = data.filter(row => {
    if (!row.Arrival_Date) return false;
    let rowDate = parseDate(row.Arrival_Date);
    // Row ki date cutoff date se badi ya barabar honi chahiye
    return rowDate >= cutoffDate && rowDate <= latestDate;
});

// Step 4: Filter kiye hue data ko wapas n8n ke format mein convert karke return karna
return filteredData.map(row => {
    return {
        json: row
    };
});
